insert into public.flashcards (id, aula_id, ordem, frente, verso) values
  ('pass-a1-f01', 'pass-a1', 1, 'Qual a diferença entre "produto" e "medicamento" de cannabis?', 'Sem registro na Anvisa é produto (a maioria dos óleos); com registro é medicamento.'),
  ('pass-a1-f02', 'pass-a1', 2, 'Qual foi o primeiro medicamento derivado de cannabis registrado no Brasil?', 'O Mevatyl.'),
  ('pass-a1-f03', 'pass-a1', 3, 'Quem foi Raphael Mechoulam?', 'Químico israelense que retomou o estudo da planta e isolou o tetra-hidrocanabinol (THC) e o canabidiol (CBD).'),
  ('pass-a1-f04', 'pass-a1', 4, 'Quem foi Elisaldo Carlini?', 'Professor brasileiro que estudou o canabidiol na epilepsia e demonstrou o efeito anticonvulsivante.'),
  ('pass-a1-f05', 'pass-a1', 5, 'Há quanto tempo a cannabis é cultivada e usada como tratamento?', 'Cultivo há cerca de 12.000 anos; uso terapêutico há cerca de 4.000 anos.'),
  ('pass-a1-f06', 'pass-a1', 6, 'Quando a cannabis foi proibida e qual motivo foi citado em aula?', 'Em 1930; um dos motivos foi a fibra da planta concorrer com o náilon da indústria.'),
  ('pass-a1-f07', 'pass-a1', 7, 'Em que parte da planta são produzidos os canabinoides?', 'Nos tricomas (glândulas em forma de cristal) da flor da planta fêmea. A planta macho não serve para o produto.'),
  ('pass-a1-f08', 'pass-a1', 8, 'Por que a planta produz canabinoides?', 'Defesa: o THC causa mal-estar, e o animal que come a planta não volta a comer.'),
  ('pass-a1-f09', 'pass-a1', 9, 'Além do THC e do CBD, o que mais há na planta?', 'Cerca de 150 outros canabinoides, além de terpenos (sabor e aroma) e flavonoides (cor), ambos anti-inflamatórios e antioxidantes.'),
  ('pass-a1-f10', 'pass-a1', 10, 'Por que os canabinoides são dados em óleo?', 'Porque são lipofílicos: dissolvem-se em gordura e óleo, não em água.'),
  ('pass-a1-f11', 'pass-a1', 11, 'Diferença entre endocanabinoide e fitocanabinoide?', 'Endocanabinoide é produzido pelo corpo (ex.: anandamida); fitocanabinoide vem da planta (ex.: THC e CBD).'),
  ('pass-a1-f12', 'pass-a1', 12, 'Como o fitocanabinoide age no sistema endocanabinoide?', 'Liga-se aos receptores canabinoides tipo 1 e tipo 2 e suplementa o sistema, fazendo-o voltar a funcionar.'),
  ('pass-a1-f13', 'pass-a1', 13, 'Qual endocanabinoide é liberado na atividade física?', 'A anandamida, ligada à sensação de bem-estar.'),
  ('pass-a1-f14', 'pass-a1', 14, 'Quais as três principais indicações do THC?', 'Dor (especialmente neuropática), apetite/náusea/vômito (quimioterapia, HIV) e sono.'),
  ('pass-a1-f15', 'pass-a1', 15, 'Quais os efeitos do THC em dose alta?', 'Ansiedade, sintomas psicóticos, taquicardia e hipotensão (sobretudo em idosos e em quem usa anti-hipertensivo).'),
  ('pass-a1-f16', 'pass-a1', 16, 'Por que o fitocanabinoide é considerado mais seguro que o benzodiazepínico em dose muito alta?', 'Benzodiazepínico em dose muito alta pode causar parada respiratória; não existe dose de fitocanabinoide que mate o paciente.'),
  ('pass-a1-f17', 'pass-a1', 17, 'Quais propriedades do canabidiol foram citadas em aula?', 'Anticonvulsivante, anti-inflamatório, ansiolítico e antipsicótico.'),
  ('pass-a1-f18', 'pass-a1', 18, 'Em quais epilepsias o canabidiol tem indicação bem estabelecida?', 'Síndrome de Dravet, síndrome de Lennox-Gastaut e esclerose tuberosa.'),
  ('pass-a1-f19', 'pass-a1', 19, 'Qual tem maior potencial anticonvulsivante: THC ou CBD?', 'O canabidiol (CBD). A professora disse que é questão de prova.'),
  ('pass-a1-f20', 'pass-a1', 20, 'Qual tem maior potencial analgésico: THC ou CBD?', 'O THC. Por isso, na dor, a professora associa os dois.'),
  ('pass-a1-f21', 'pass-a1', 21, 'Compare THC e CBD quanto a sono e apetite.', 'THC: induz o sono e estimula o apetite. CBD: promove vigília e reduz o apetite.'),
  ('pass-a1-f22', 'pass-a1', 22, 'Compare THC e CBD quanto à pressão intraocular.', 'THC pode reduzir; CBD pode aumentar. Por isso, pergunte sempre se o paciente tem glaucoma.'),
  ('pass-a1-f23', 'pass-a1', 23, 'O efeito hipotensor do THC serve para tratar hipertensão?', 'Não. É efeito adverso, sobretudo no idoso e no hipertenso em tratamento.'),
  ('pass-a1-f24', 'pass-a1', 24, 'O que é o efeito comitiva (entourage)?', 'Sinergia entre canabinoides, terpenos e flavonoides: mais eficácia, menos efeito colateral e menos gotas (mais economia).'),
  ('pass-a1-f25', 'pass-a1', 25, 'Em quais áreas da oncologia os fitocanabinoides são usados?', 'Náusea, vômito e falta de apetite na quimioterapia, e dor. A professora marcou a oncologia como questão de prova.'),
  ('pass-a1-f26', 'pass-a1', 26, 'O que é redução de danos, no contexto da cannabis?', 'Trocar uma forma de uso mais danosa por outra menos danosa, como a cannabis fumada pelo óleo.'),
  ('pass-a1-f27', 'pass-a1', 27, 'Qual é a "regra de ouro" da anamnese antes de prescrever?', 'Esquizofrenia na família, transtorno bipolar ou psicose: THC fora. No máximo, óleo isolado de CBD avaliado caso a caso.'),
  ('pass-a1-f28', 'pass-a1', 28, 'Por que o THC é contraindicado em quem tem genética para psicose?', 'Porque pode abrir o quadro psicótico nessas pessoas.'),
  ('pass-a1-f29', 'pass-a1', 29, 'Quais as três contraindicações citadas em aula?', 'Psicoses, transtornos de personalidade e transtorno afetivo bipolar.'),
  ('pass-a1-f30', 'pass-a1', 30, 'Quais os efeitos colaterais que o paciente deve ser avisado?', 'Boca seca e olho seco, tontura, agitação e insônia (THC em dose alta) e sintomas psicóticos (THC, em suscetíveis).'),
  ('pass-a1-f31', 'pass-a1', 31, 'Em quais situações a professora não prescreve?', 'Gestação e amamentação (jamais), menores de 5 anos, doença do fígado (ex.: hepatite C) e doença cardiovascular descompensada.'),
  ('pass-a1-f32', 'pass-a1', 32, 'Qual remédio foi citado como exemplo de interação com fitocanabinoides?', 'A varfarina.'),
  ('pass-a1-f33', 'pass-a1', 33, 'Qual a dose inicial da receita-modelo e como titular?', '1 gota sublingual de manhã e 1 à noite; aumento semanal até o teto escrito na receita, com conversa semanal com o paciente.'),
  ('pass-a1-f34', 'pass-a1', 34, 'Qual o erro de prescrição que a professora mais vê?', 'Passar "umas gotinhas para ver o que dá", sem titulação: o paciente não melhora e desacredita do tratamento.'),
  ('pass-a1-f35', 'pass-a1', 35, 'Quem pode prescrever derivados de cannabis?', 'Qualquer médico (não só especialista) e também o dentista.'),
  ('pass-a1-f36', 'pass-a1', 36, 'Quais os três documentos que a professora entrega ao paciente?', 'Receita, laudo e termo de consentimento livre e esclarecido (assinado pelo paciente).'),
  ('pass-a1-f37', 'pass-a1', 37, 'Quais os caminhos para o paciente conseguir o produto?', 'Farmácia, associação, importação pelo portal gov.br ou cultivo doméstico com autorização judicial.'),
  ('pass-a1-f38', 'pass-a1', 38, 'Qual receita é usada hoje para produto com até 0,2% de THC?', 'Receita de controle especial, branca, em duas vias (antes era a azul).'),
  ('pass-a1-f39', 'pass-a1', 39, 'Qual receita é usada para produto com mais de 0,2% de THC?', 'Receita amarela (notificação de receita A).'),
  ('pass-a1-f40', 'pass-a1', 40, 'O que é exigido para o cultivo doméstico de cannabis?', 'Laudo de engenheiro agrônomo e petição ao juiz para obter autorização judicial.')
